using System.Runtime.InteropServices;

namespace CatalogSvc;

public readonly record struct ProductInfo(string Category, decimal Price);

public class ProductCatalog
{
    private readonly Dictionary<string, ProductInfo> _products = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, List<string>> _categoryIndex = new(StringComparer.OrdinalIgnoreCase);

    // Frozen snapshots for read-heavy hot paths
    private FrozenDictionary<string, ProductInfo>? _frozenProducts;
    private FrozenDictionary<string, string[]>? _frozenCategories;

    public void AddProduct(string code, string category, decimal price)
    {
        _products[code] = new ProductInfo(category, price);

        ref var list = ref CollectionsMarshal.GetValueRefOrAddDefault(
            _categoryIndex, category, out bool existed);
        if (!existed)
            list = new List<string>();
        list!.Add(code);

        // Invalidate frozen snapshots on mutation
        _frozenProducts = null;
        _frozenCategories = null;
    }

    /// <summary>Freeze the catalog for optimized read throughput.</summary>
    public void Freeze()
    {
        _frozenProducts = _products.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _frozenCategories = _categoryIndex
            .ToFrozenDictionary(kvp => kvp.Key, kvp => kvp.Value.ToArray(), StringComparer.OrdinalIgnoreCase);
    }

    public string? GetCategory(string code)
    {
        var lookup = (IReadOnlyDictionary<string, ProductInfo>?)_frozenProducts ?? _products;
        return lookup.TryGetValue(code, out var info) ? info.Category : null;
    }

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        var lookup = (IReadOnlyDictionary<string, ProductInfo>?)_frozenProducts ?? _products;
        decimal total = 0m;
        foreach (var code in codes)
        {
            if (lookup.TryGetValue(code, out var info))
                total += info.Price;
        }
        return total;
    }

    public IReadOnlyList<string> GetProductsByCategory(string category)
    {
        // O(1) reverse-index lookup instead of full scan
        if (_frozenCategories is { } frozen)
            return frozen.TryGetValue(category, out var arr) ? arr : [];

        return _categoryIndex.TryGetValue(category, out var list) ? list : [];
    }
}

